// Original generic span_to_source FnMut/result ownership and ambient runtime.
use std::{cell::{Cell,RefCell},io,path::{Path,PathBuf},sync::{Arc,atomic::{AtomicUsize,Ordering}},panic::{catch_unwind,AssertUnwindSafe}};
use rustc_span::{BytePos,Span,FileName,RealFileName,SourceFile,SourceFileHashAlgorithm,SpanSnippetError};use rustc_span::def_id::CrateNum;
use rustc_span::source_map::{SourceMap,SourceMapInputs,FilePathMapping,FileLoader};
const TEXT:&str=" aλz";static ADDRESS:AtomicUsize=AtomicUsize::new(0);static READS:AtomicUsize=AtomicUsize::new(0);
struct Loader;
impl FileLoader for Loader{fn file_exists(&self,_:&Path)->bool{true}fn read_file(&self,_:&Path)->io::Result<String>{READS.fetch_add(1,Ordering::SeqCst);Ok(TEXT.into())}fn read_binary_file(&self,_:&Path)->io::Result<Arc<[u8]>>{Ok(Arc::from(TEXT.as_bytes()))}fn current_directory(&self)->io::Result<PathBuf>{Ok("/proof".into())}}
struct Setup{sm:SourceMap,local:Arc<SourceFile>,foreign:Arc<SourceFile>}
thread_local!{static SETUP:RefCell<Option<Setup>>=const{RefCell::new(None)};}
fn body_panic(){panic!("body")}
fn env_panic(){panic!("env")}
fn outer_panic(){panic!("outer")}
struct Env<'a>{file:&'a Arc<SourceFile>,calls:Cell<usize>,panic:bool,tag:Vec<u8>}
impl Env<'_>{fn call(&self,src:&str,start:usize,end:usize){assert_eq!(self.tag,[1,2]);ADDRESS.store(self as*const Self as usize,Ordering::SeqCst);self.calls.set(self.calls.get()+1);let borrowed=if let Some(local)=&self.file.src{std::ptr::eq(src.as_ptr(),local.as_ptr())}else{std::ptr::eq(src.as_ptr(),self.file.external_src.read().get_source().unwrap().as_ptr())};println!("call:{start}:{end}:{borrowed}:{}:{}:{}",Arc::strong_count(self.file),READS.load(Ordering::SeqCst),std::thread::panicking());}}
impl Env<'_>{fn pred(&self,c:char){ADDRESS.store(self as*const Self as usize,Ordering::SeqCst);self.calls.set(self.calls.get()+1);println!("pred:{:x}:{}:{}:{}",c as u32,Arc::strong_count(self.file),READS.load(Ordering::SeqCst),std::thread::panicking());}}
impl Drop for Env<'_>{fn drop(&mut self){let old=ADDRESS.load(Ordering::SeqCst);let writable=self.file.external_src.try_write().is_some();println!("env_drop:{}:{}:{}:{writable}:{}",self.calls.get(),old==0||old==self as*const Self as usize,Arc::strong_count(self.file),std::thread::panicking());if self.panic{env_panic();}}}
struct Value(Vec<u8>);impl Drop for Value{fn drop(&mut self){assert_eq!(self.0,[7,8]);println!("value_drop:{}",std::thread::panicking())}}
fn invoke(input:&str,action:&str){SETUP.with(|slot|{let setup=slot.borrow();let setup=setup.as_ref().unwrap();let f=setup.foreign.start_pos.0;let(lo,hi,file)=match input{"local"=>(0,2,&setup.local),"external"=>(f,f+2,&setup.foreign),"bad"=>(f+99,f+100,&setup.foreign),"distinct"=>(0,f+1,&setup.local),_=>unreachable!()};let env=Env{file,calls:Cell::new(0),panic:action=="env"||action=="both",tag:vec![1,2]};let result=setup.sm.span_to_source(Span::with_root_ctxt(BytePos(lo),BytePos(hi)),move|src,start,end|{env.call(src,start,end);if action=="body"||action=="both"{body_panic()}Ok(Value(vec![7,8]))});match result{Ok(v)=>{println!("result:ok:{}",std::thread::panicking());drop(v)},Err(e)=>{let tag=match e{SpanSnippetError::DistinctSources(_)=>"distinct",SpanSnippetError::MalformedForSourcemap(_)=>"malformed",_=>"other"};println!("result:{tag}:{}",std::thread::panicking())}}});}
fn invoke_predicate(input:&str,action:&str,op:&str){SETUP.with(|slot|{let s=slot.borrow();let s=s.as_ref().unwrap();let f=s.foreign.start_pos.0;let(lo,hi,file)=match input{"local"=>if op=="prev"{(2,4,&s.local)}else{(0,2,&s.local)},"external"=>if op=="prev"{(f+2,f+4,&s.foreign)}else{(f,f+2,&s.foreign)},"bad"=>(f+99,f+100,&s.foreign),"distinct"=>(0,f+1,&s.local),_=>unreachable!()};let env=Env{file,calls:Cell::new(0),panic:action=="env"||action=="both",tag:vec![1,2]};let span=Span::with_root_ctxt(BytePos(lo),BytePos(hi));let result=match op{"while"=>s.sm.span_extend_while(span,move|c|{env.pred(c);if action=="body"||action=="both"{body_panic()}true}),"prev"=>s.sm.span_extend_prev_while(span,move|c|{env.pred(c);if action=="body"||action=="both"{body_panic()}true}),"take"=>Ok(s.sm.span_take_while(span,move|c|{env.pred(*c);if action=="body"||action=="both"{body_panic()}true})),_=>unreachable!()};match result{Ok(out)=>println!("result:span:{}:{}:{}",out.lo().0,out.hi().0,std::thread::panicking()),Err(e)=>println!("result:{}:{}",match e{SpanSnippetError::DistinctSources(_)=>"distinct",SpanSnippetError::MalformedForSourcemap(_)=>"malformed",_=>"other"},std::thread::panicking())}});}
fn invoke_selected(input:&str,action:&str){let op=std::env::args().nth(4).unwrap_or("extract".into());if op=="extract"{invoke(input,action)}else{invoke_predicate(input,action,&op)}}
fn report(f:impl FnOnce()){let result=catch_unwind(AssertUnwindSafe(f));let tag=match result{Ok(())=>"none",Err(ref p)=>p.downcast_ref::<&str>().copied().unwrap_or("other")};println!("caught:{tag}:{}",std::thread::panicking());}
struct Outer{input:String,action:String,caught:bool}impl Drop for Outer{fn drop(&mut self){println!("outer_drop:{}",std::thread::panicking());if self.caught{report(||invoke_selected(&self.input,&self.action))}else{invoke_selected(&self.input,&self.action)}}}
fn main(){let args:Vec<String>=std::env::args().collect();let(mode,input,action)=(args[1].clone(),args[2].clone(),args[3].clone());rustc_data_structures::sync::set_dyn_thread_safe_mode(true);rustc_span::create_default_session_globals_then(||{let sm=SourceMap::with_inputs(SourceMapInputs{file_loader:Box::new(Loader),path_mapping:FilePathMapping::empty(),hash_kind:SourceFileHashAlgorithm::Md5,checksum_hash_kind:None});let local=sm.new_source_file(FileName::Custom("local.rs".into()),TEXT.into());let t=SourceFile::new(FileName::Real(RealFileName::from_virtual_path(Path::new("foreign.rs"))),TEXT.into(),SourceFileHashAlgorithm::Md5,None).unwrap();let foreign=sm.new_imported_source_file(t.name,t.src_hash,t.checksum_hash,t.stable_id,t.normalized_source_len.0,t.unnormalized_source_len,CrateNum::from_u32(1),t.lines,t.multibyte_chars,t.normalized_pos,0);SETUP.with(|v|*v.borrow_mut()=Some(Setup{sm,local,foreign}));std::panic::set_hook(Box::new(move|p|{let l=p.location().unwrap();let file=if l.file().ends_with("owned_extract.rs"){"owned_extract.rs"}else{l.file()};let kind=if p.payload().is::<String>(){"owned_string"}else{"static_str"};println!("hook:{kind}:{file}:{}:{}:{}",l.line(),l.column(),p.payload_as_str().unwrap_or("opaque"));if mode=="processing"&&p.payload_as_str()==Some("outer"){invoke_selected(&input,&action);println!("hook_return:{}",std::thread::panicking());}}));let(mode,input,action)=(&args[1],&args[2],&args[3]);match mode.as_str(){"normal"=>report(||invoke_selected(input,action)),"processing"=>report(outer_panic),"inherited_caught"|"inherited_escape"=>report(||{let _outer=Outer{input:input.clone(),action:action.clone(),caught:mode=="inherited_caught"};outer_panic()}),_=>unreachable!()};SETUP.with(|v|*v.borrow_mut()=None);});}
